/bin/zsh -lc "python3 - <<'PY'
import zipfile,glob,xml.etree.ElementTree as E
ns={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
for p in sorted(glob.glob('docs/liitteet/*')):
 print('\\nFILE',p)
 with zipfile.ZipFile(p) as z:
  strings=[]
  if 'xl/sharedStrings.xml' in z.namelist():
   strings=[''.join(i.itertext()) for i in E.fromstring(z.read('xl/sharedStrings.xml'))]
  print(z.read('xl/workbook.xml').decode())
  for name in z.namelist():
   if name.startswith('xl/worksheets/sheet') and name.endswith('.xml'):
    print('SHEET',name)
    root=E.fromstring(z.read(name))
    for row in root.findall('.//s:row',ns):
     vals=[]
     for c in row:
      t=c.get('t');v=c.find('s:v',ns)
      txt=v.text if v is not None else ''.join(c.itertext())
      if t=='s':txt=strings[int(txt)]
      vals.append(c.get('r','')+'='+str(txt))
     print(' | '.join(vals))
PY"

